(window.CRAM_PERSONAL=window.CRAM_PERSONAL||{})["pharmacology-i-exam-2"]={"title":"Pharmacology I Exam 2","sections":[{"id":"rules","title":"What is NOT on it","style":"--acc:#8c1d12;--acc-bg:#efdfde;--acc-zebra:#f7efee;--acc-ink:#6d170e"},{"id":"kinetics","title":"Delivery & kinetics","style":"--acc:#2f4f6b;--acc-bg:#e2e6ea;--acc-zebra:#f0f3f5;--acc-ink:#253e53"},{"id":"abx","title":"Ocular antibiotics","style":"--acc:#1f6f5c;--acc-bg:#e0ebe8;--acc-zebra:#eff5f4;--acc-ink:#185748"},{"id":"viral","title":"Antivirals & antifungals","style":"--acc:#7a4a9c;--acc-bg:#ece6f1;--acc-zebra:#f6f2f8;--acc-ink:#5f3a7a"},{"id":"allergy","title":"Allergy","style":"--acc:#a8562f;--acc-bg:#f3e7e2;--acc-zebra:#f9f3f0;--acc-ink:#834325"},{"id":"inflam","title":"Anti-inflammatories & dry eye","style":"--acc:#b8862f;--acc-bg:#f5eee2;--acc-zebra:#faf7f0;--acc-ink:#906925"},{"id":"glaucoma","title":"Glaucoma","style":"--acc:#4a4f8c;--acc-bg:#e6e6ef;--acc-zebra:#f2f3f7;--acc-ink:#3a3e6d"},{"id":"diag","title":"Diagnostic agents & administration","style":"--acc:#3d6b52;--acc-bg:#e4eae7;--acc-zebra:#f1f5f3;--acc-ink:#305340"},{"id":"ent-abx","title":"ENT · antibiotics & antifungals","style":"--acc:#2f6f8c;--acc-bg:#e2ebef;--acc-zebra:#f0f5f7;--acc-ink:#25576d"},{"id":"ent-pain","title":"ENT · aspirin, NSAIDs, acetaminophen","style":"--acc:#8c4a2f;--acc-bg:#efe6e2;--acc-zebra:#f7f2f0;--acc-ink:#6d3a25"},{"id":"ent-hist","title":"ENT · antihistamines & steroids","style":"--acc:#5b4a8a;--acc-bg:#e8e6ef;--acc-zebra:#f4f2f7;--acc-ink:#473a6c"},{"id":"ent-cough","title":"ENT · decongestants & cough","style":"--acc:#3d6b52;--acc-bg:#e4eae7;--acc-zebra:#f1f5f3;--acc-ink:#305340"},{"id":"htn-rules","title":"Antihypertensives · scope & RAAS drugs","style":"--acc:#8c1d3a;--acc-bg:#efdfe3;--acc-zebra:#f7eff1;--acc-ink:#6d172d"},{"id":"htn-ccb","title":"Antihypertensives · calcium channel blockers","style":"--acc:#b0592b;--acc-bg:#f4e8e1;--acc-zebra:#f9f3f0;--acc-ink:#894522"},{"id":"htn-bb","title":"Antihypertensives · beta blockers","style":"--acc:#4a4f8c;--acc-bg:#e6e6ef;--acc-zebra:#f2f3f7;--acc-ink:#3a3e6d"},{"id":"htn-other","title":"Antihypertensives · alpha, central, vasodilators, algorithm","style":"--acc:#2f6560;--acc-bg:#e2e9e9;--acc-zebra:#f0f4f4;--acc-ink:#254f4b"},{"id":"lip-aid","title":"Lipids · scope & memory aid","style":"--acc:#7a3b6b;--acc-bg:#ece4ea;--acc-zebra:#f6f1f5;--acc-ink:#5f2e53"},{"id":"lip-statin","title":"Lipids · statins & guidelines","style":"--acc:#1f6f5c;--acc-bg:#e0ebe8;--acc-zebra:#eff5f4;--acc-ink:#185748"},{"id":"lip-other","title":"Lipids · ezetimibe, resins, fibrates, niacin, PCSK9","style":"--acc:#a2681c;--acc-bg:#f2eadf;--acc-zebra:#f8f4ef;--acc-ink:#7e5116"}],"rows":[{"t":"Dosing","d":"&ldquo;Not for memorization sake necessarily, because you can always look up the dosing for a medication <b>if you know which drug you actually want to use in the first place</b>.&rdquo; The deck is full of regimens. Learn none of them.","s":0},{"t":"Formulations","d":"&ldquo;I don&rsquo;t care that you memorize that necessarily, with some exceptions.&rdquo; Percent strengths, solution against ointment: not the question.","s":0},{"t":"That ONE indications table","d":"&ldquo;Don&rsquo;t worry so much about indications for use&hellip; a lot of them have a lot of crossover.&rdquo; He means the slide listing ten antibiotics against overlapping indications &mdash; orientation, not content. <b>What each agent is FOR is still asked.</b>","s":0},{"t":"Which agent irritates","d":"&ldquo;Don&rsquo;t memorize which ones cause eye irritation or hypersensitivity. <b>Any of these can do that.</b>&rdquo; That is about the GENERIC irritation. <b>The effects that name one drug are fair game</b> &mdash; ciprofloxacin&rsquo;s white precipitate, the bitter taste of the carbonic anhydrase inhibitors, iris color change with the prostaglandins.","s":0},{"t":"Combination products","d":"&ldquo;The specific combinations, I don&rsquo;t care that you memorize, <b>BUT</b> just know if I was to say, hey, patient&rsquo;s on this drug right now, what would be a helpful second line agent to add on?&rdquo; Products out, reasoning in.","s":0},{"t":"&#9733; What IS promised","d":"&ldquo;<b>I will tell you, I will ask this question</b>&hellip; there&rsquo;s rebound hyperemia.&rdquo; It is in the allergy block below.","s":0},{"t":"ONE variable","d":"<b>Time in contact with the eye.</b> Gels, ointments and solid inserts exist to prolong contact in the cul-de-sac. So does blocking the tear ducts with silicone plugs or cautery.","s":1},{"t":"Two routes, two effects","d":"<b>TRANSCORNEAL &rarr; local effect.</b> Has a lag time; rate depends on the CONCENTRATION GRADIENT, governed by <b>Fick&rsquo;s law</b>. <b>NASOLACRIMAL &rarr; systemic effect</b>, and it <b>AVOIDS FIRST-PASS METABOLISM</b> &mdash; which is why a topical beta blocker can drop a heart rate.","s":1},{"t":"Four absorption determinants","d":"Time in cul-de-sac and tear film &middot; nasolacrimal drainage &middot; protein binding &middot; diffusion across cornea and conjunctiva.","s":1},{"t":"Prodrugs activated IN the eye","d":"<b>Dipivefrin &rarr; epinephrine. Latanoprost &rarr; prostaglandin F2-alpha.</b> Some drugs instead ACCUMULATE &mdash; chloroquine&rsquo;s <b>bull&rsquo;s eye lesion</b>.","s":1},{"t":"Route trade-offs","d":"TOPICAL: convenient, economical, safe; costs compliance, surface toxicity, systemic absorption. PERIOCULAR (subconjunctival, sub-Tenon&rsquo;s, retrobulbar): reaches posterior uveitis and cystoid macular edema; risks <b>globe perforation, optic nerve trauma, retinal vessel occlusion</b>. INTRACAMERAL: prompt, anterior segment, short-lived.","s":1},{"t":"★ THE MECHANISM PAIR","d":"<b>Macrolides &rarr; 50S</b> (block transpeptidation). <b>Aminoglycosides &rarr; 30S.</b> Same endpoint, different subunit.","s":2},{"t":"The other mechanisms","d":"<b>Fluoroquinolones</b> &rarr; DNA gyrase + topoisomerase IV, double-stranded breakage. <b>Bacitracin</b> &rarr; blocks mucopeptide transfer into the CELL WALL. <b>Polymyxin B</b> &rarr; binds membrane phospholipids, contents leak. <b>Sulfacetamide</b> &rarr; antagonizes PABA. <b>Trimethoprim</b> &rarr; blocks reduction to tetrahydrofolate. (The last two are the same pathway, one step apart.)","s":2},{"t":"★ DRUG CHOICE","d":"<b>Erythromycin</b> = commonest, SOOTHING, usable before a bacterial cause is confirmed; also ophthalmia neonatorum prophylaxis. <b>Fluoroquinolone</b> = corneal ulcers, suspected <b>Pseudomonas</b>, and therefore CONTACT LENS wearers once keratitis is excluded. <b>Azithromycin</b> = twice daily instead of 4+, but expensive and used less.","s":2},{"t":"The only two adverse effects that name a drug","d":"<b>Ciprofloxacin &rarr; white precipitate in ~17%.</b> <b>Aminoglycoside over several days &rarr; corneal ulceration and reactive keratoconjunctivitis.</b> Everything else irritates.","s":2},{"t":"The only hard contraindication","d":"<b>Sulfacetamide in sulfonamide allergy.</b>","s":2},{"t":"Conjunctivitis context","d":"Most is NOT bacterial: viruses, allergy, irritants, contact lenses. Bacteria: <b>Neisseria, Haemophilus, Strep pneumoniae, Staph aureus, Moraxella</b>. Treat empirically, broad spectrum, <b>no cultures unless an unusual organism is expected</b>.","s":2},{"t":"★ NO antiviral for adenoviral conjunctivitis","d":"Self-limited; symptomatic relief only. Antivirals exist for <b>keratitis, herpes zoster ophthalmicus, retinitis</b>.","s":3},{"t":"Topical antivirals","d":"<b>Trifluridine</b> &rarr; inhibits thymidylate synthetase AND substitutes for thymidine in viral DNA. <b>Ganciclovir</b> &rarr; competitively inhibits dGTP binding to DNA polymerase; intravitreal for CMV retinitis.","s":3},{"t":"Systemic antivirals","d":"<b>Acyclovir, valacyclovir, famciclovir</b> oral &mdash; zoster ophthalmicus, simplex keratitis. <b>Foscarnet</b> intravenous &mdash; CMV retinitis.","s":3},{"t":"★ Natamycin","d":"<b>The ONLY commercially available ophthalmic antifungal.</b> Polyene &mdash; binds sterol, increases membrane permeability. Covers Aspergillus, Candida, Cephalosporium, <b>Fusarium</b>, Penicillium. <b>Amphotericin B</b> is the one with every route (topical, subconjunctival, intravitreal, intravenous).","s":3},{"t":"★ Fungal risk factors","d":"Trauma &middot; chronic ocular surface disease &middot; contact lens wear &middot; immunosuppression &mdash; <b>including topical steroid use</b>. The only one a prescription creates.","s":3},{"t":"★★ REBOUND HYPEREMIA","d":"The promised question. OTC redness drops are <b>alpha-1 agonists</b> &rarr; vasoconstriction. Constant activation <b>DOWNREGULATES the receptors</b> &rarr; on stopping, fewer receptors for endogenous catecholamines &rarr; <b>vessels blow open</b>. Use <b>&lt;2 weeks</b>; no improvement in <b>72 hours</b> &rarr; stop and be seen.","s":4},{"t":"★ Imidazoline ingestion","d":"<b>LOCALLY alpha-1. SYSTEMICALLY alpha-2.</b> That is why a toddler who swallows the bottle gets CNS depression and apnea, not hypertension. Same receptor logic as the brimonidine age limit.","s":4},{"t":"H1 agents","d":"<b>Not antagonists &mdash; INVERSE AGONISTS</b> that inactivate the receptor, still competitive with histamine. Onset <b>minutes</b>; allow <b>2 weeks</b> for full efficacy. Typically preferred over mast cell stabilizers. Can worsen dryness.","s":4},{"t":"Mast cell stabilizers","d":"Cromolyn, lodoxamide, nedocromil. Inhibit degranulation (histamine, tryptase, PGD2). <b>5&ndash;14 days</b> to full effect &mdash; <b>NOT for acute symptoms</b>. Often 4&times; daily. For predictable seasonal allergy in someone intolerant of alternatives.","s":4},{"t":"The cascade","d":"IgE binds Fc receptors on <b>mast cells and basophils</b>; tyrosine kinases in <b>5&ndash;15 seconds</b>; histamine, PAF, leukotrienes &rarr; vasodilation, swelling, redness, itch.","s":4},{"t":"★ One step apart","d":"<b>STEROIDS inhibit phospholipase A2</b> &mdash; arachidonic acid never liberated, whole cascade fails. <b>NSAIDs block cyclooxygenase</b> &mdash; only the prostaglandin/thromboxane arm.","s":5},{"t":"NSAIDs","d":"Bromfenac, diclofenac, flurbiprofen, ketorolac, nepafenac. For <b>postoperative inflammation and pain</b> and allergic conjunctivitis; <b>NOT routinely for conjunctivitis</b>. Adverse: lacrimation, keratitis, <b>raised IOP</b>.","s":5},{"t":"★ Steroid risks &rarr; &lt;2 week pulse","d":"Cataract &middot; raised IOP and glaucoma (<b>more with family history</b>) &middot; infection &middot; delayed wound healing &middot; corneal ulcers. Also inhibit fibrin/collagen deposition &rarr; less scarring.","s":5},{"t":"★ &ldquo;Soft steroids&rdquo;","d":"<b>Fluorometholone, loteprednol, rimexolone</b> &mdash; lower IOP risk. Triamcinolone = intravitreal.","s":5},{"t":"Dry eye order","d":"<b>TREAT THE DISEASE FIRST</b> (Sjogren, rheumatoid, vitamin A deficiency, Stevens-Johnson). Then punctal plugs or surgical occlusion, then tear substitutes (electrolytes + surfactants + <b>thickeners to prolong cul-de-sac time</b>).","s":5},{"t":"Cyclosporine","d":"Inhibits <b>interleukin-2</b> &rarr; less T cell activation &rarr; less lacrimal gland inflammation &rarr; more tears. For <b>chronic dry eye WITH inflammation</b>. Warn: <b>burning in ~17%</b>.","s":5},{"t":"★ Sort every drug by side","d":"<b>INCREASE OUTFLOW:</b> prostaglandins, alpha agonists, cholinergics. <b>DECREASE PRODUCTION:</b> alpha agonists, beta blockers, carbonic anhydrase inhibitors. <b>Alpha agonists are on BOTH</b> &mdash; that is where the errors come from.","s":6},{"t":"The three definitions","d":"<b>Ocular hypertension</b> = high pressure, NO nerve damage, NO field loss. <b>Open angle</b> = increased production or decreased drainage; may have damage. <b>Angle closure</b> = blocked canal, often normal nerve, usually acute PAIN. Normal IOP <b>10&ndash;21 mmHg</b>. Drugs target OPEN angle.","s":6},{"t":"★ Prostaglandins","d":"<b>FIRST LINE, most commonly used.</b> Increase outflow. <b>ONCE DAILY &mdash; exceeding it INHIBITS the effect.</b> Warn: <b>eyelash length and IRIS COLOR change</b>, hyperemia. Latanoprost, travoprost, bimatoprost, tafluprost.","s":6},{"t":"★ Beta blockers","d":"Block beta receptors in ciliary epithelium &rarr; less cAMP &rarr; less production. <b>Betaxolol = beta-1 SELECTIVE</b> (safer in asthma). Carteolol, timolol, levobunolol = non-selective, more efficacious, more risk. Systemic: <b>heart failure, bradycardia, heart block, airway resistance</b>.","s":6},{"t":"★ Alpha-2 agonists","d":"Apraclonidine, brimonidine. Reduce production AND increase outflow. <b>CONTRAINDICATED UNDER 2 YEARS &mdash; CNS depression and apnea.</b> Apraclonidine ionized &rarr; less blood-brain penetration; brimonidine lipophilic but less allergic conjunctivitis.","s":6},{"t":"Carbonic anhydrase inhibitors","d":"Dorzolamide, brinzolamide. Less bicarbonate &rarr; less fluid. Tolerability is the issue: <b>bitter taste ~25%, stinging ~33%</b>.","s":6},{"t":"Cholinergics","d":"Pilocarpine, carbachol, acetylcholine. Muscarinic &rarr; ciliary muscle contracts &rarr; outflow opens. <b>Fixed small pupils, myopia, blurring</b> &mdash; <b>young patients cannot tolerate it</b>.","s":6},{"t":"★ Treat / target","d":"Treat those <b>with risk factors</b>; monitor those without. Start with a <b>prostaglandin or beta blocker</b>, optionally <b>one eye</b> as its own control. Goal: <b>20&ndash;30% reduction</b>. Combinations are synergistic across DIFFERENT routes.","s":6},{"t":"★ Anesthetics","d":"Tetracaine, proparacaine. Inhibit <b>sodium influx</b>. For tonometry, foreign body removal, superficial corneal surgery. <b>Numb 10&ndash;20 min with NO BLINK REFLEX.</b> <b>DO NOT PRESCRIBE</b> &mdash; repeated use is epithelial-toxic and delays healing.","s":7},{"t":"Cycloplegics &mdash; two routes","d":"<b>ANTIMUSCARINICS</b> (atropine, cyclopentolate, tropicamide) block muscarinic receptors &rarr; mydriasis. <b>SYMPATHOMIMETIC</b> (phenylephrine) stimulates the dilator &rarr; pupil stays <b>more light-reactive</b>. Uses: fundoscopy; uveitis to prevent synechiae and relieve ciliary spasm.","s":7},{"t":"Fluorescein","d":"Reveals <b>epithelial defects of cornea and conjunctiva</b>. Anterior segment staining; discloses corneal injury.","s":7},{"t":"★ BEFORE any drop","d":"<b>MEASURE VISUAL ACUITY.</b> Document allergies and last eye exam. Repeat acuity every visit &mdash; <b>if it worsens, immediate ophthalmology consult</b>.","s":7},{"t":"Instillation","d":"<b>Wash hands (most important)</b> &rarr; dropper touches nothing &rarr; head back, lower lid pocket &rarr; one drop &rarr; close eyes, tilt forward, <b>finger over lacrimal duct</b> &rarr; hold <b>2&ndash;3 minutes</b> &rarr; wipe, wash again.","s":7},{"t":"Ointments &amp; lenses","d":"Ointment suits <b>children and poor compliers</b> (works even from the lashes); ribbon into the pocket, <b>no duct occlusion needed</b>; <b>blurs vision ~20 min</b>. Contact lenses: stop; resume after <b>24 h free of inflammation and discharge</b>; discard or disinfect the lens; bin the eye makeup.","s":7},{"t":"Same 3 bugs","d":"Otitis media and sinusitis: <b>S. pneumoniae, H. influenzae, M. catarrhalis</b> (sinusitis adds S. pyogenes, S. aureus, gram-negative bacilli). Pharyngitis: mostly viral; group A strep in 15&ndash;30%.","s":8},{"t":"Otitis media","d":"<b>High-dose amoxicillin</b> (overcomes pneumococcal resistance). Severe/resistant or antibiotics in the last month &rarr; <b>amoxicillin-clavulanate</b>. Penicillin allergy &rarr; cefdinir or azithromycin (up to 50% of pneumococci macrolide-resistant). <b>No improvement in 3 days = failure</b> &rarr; amoxicillin-clavulanate or cefdinir &rarr; <b>ceftriaxone</b> intramuscular/intravenous.","s":8},{"t":"Sinusitis","d":"Bacterial only if <b>&gt;10 days or worsening</b>. <b>Amoxicillin-clavulanate</b> (beta-lactamase <i>H. influenzae</i>). Allergy &rarr; <b>clindamycin + cefixime</b>, or <b>levofloxacin</b>. Saline irrigation helps.","s":8},{"t":"Pharyngitis","d":"Goal: prevent <b>rheumatic fever</b> and suppurative complications. <b>Rapid strep test</b> first. Amoxicillin 10 days or <b>benzathine penicillin G</b> once. Allergy: cephalexin, clindamycin, azithromycin.","s":8},{"t":"Otic drops","d":"Antibiotic + steroid (growth &darr; + cytokines &darr;). <b>Polymyxin B: NOT with ruptured eardrum or tubes</b> &mdash; cochlear damage, hearing loss. Neomycin &rarr; hypersensitivity. Ciprofloxacin/dexamethasone = expensive &rarr; ofloxacin + dexamethasone ophthalmic.","s":8},{"t":"Antifungals","d":"<b>Nystatin</b>: NOT absorbed; binds membrane sterols; <b>oral thrush</b> (inhaled steroids, HIV/AIDS (human immunodeficiency virus and acquired immunodeficiency syndrome), chemotherapy); only GI (gastrointestinal) effects. <b>Ketoconazole</b>: systemic fungal infection; <b>CYP3A4 (cytochrome P450 3A4) inhibitor</b>; <b>QTc (corrected QT interval) prolongation</b>; hepatitis &rarr; hepatic failure; hyperlipidemia, orthostatic hypotension.","s":8},{"t":"Aspirin","d":"<b>IRREVERSIBLE</b>, noncompetitive platelet inhibitor; non-selective COX-1/COX-2 (cyclooxygenase-1 and -2) (cyclooxygenase). Oral &rarr; hepatic conjugation &rarr; renal excretion.","s":9},{"t":"The ladder (no grams)","d":"Antiplatelet &rarr; analgesic/antipyretic &rarr; anti-inflammatory (<b>TINNITUS</b>) &rarr; salicylism: hyperventilation + alkalosis &rarr; fever, dehydration, <b>metabolic acidosis</b> &rarr; shock, coma, death.","s":9},{"t":"Aspirin contraindications","d":"Bleeding disorders &middot; pregnancy (very low dose may help pre-eclampsia) &middot; <b>child with viral fever (chickenpox, influenza) &rarr; REYE SYNDROME</b>.","s":9},{"t":"Reye syndrome","d":"Under 15; <b>50% mortality</b>; vomiting, progressive CNS (central nervous system) damage, hepatic injury, <b>hypoglycemia</b>; fatty liver, cerebral edema; 5 stages ending in seizures and death.","s":9},{"t":"Ibuprofen","d":"<b>REVERSIBLE</b> COX-1/2 (cyclooxygenase-1 and -2) inhibitor. Ulcers/bleeding, edema, <b>acute renal failure</b>. Interactions: &darr; ACE-inhibitor effect; diuretics &rarr; renal failure; &uarr; <b>lithium</b> and <b>methotrexate</b> (toxic); anticoagulants &rarr; GI (gastrointestinal) bleeds. Avoid: asthma, <b>under 6 months</b>, ulcer history, renal dysfunction. Naproxen = longer half-life.","s":9},{"t":"Acetaminophen","d":"Analgesic + antipyretic, NOT anti-inflammatory; mechanism unclear; well tolerated. <b>Chronic alcohol &rarr; liver damage.</b>","s":9},{"t":"Triple response","d":"Redness (direct vasodilation) &middot; wheal (post-capillary permeability) &middot; flare (axon-reflex vasodilation). H1: permeability, bronchoconstriction, itch. H2: gastric acid, cardiac contractility.","s":10},{"t":"1st vs 2nd generation","d":"<b>1st generation enters the CNS (central nervous system)</b> + hits muscarinic/serotonin receptors &rarr; <b>SEDATION</b> (additive with alcohol; doxylamine sleep aid), antiemetic, dry mouth, urinary retention, blurred vision; excitation in children/overdose. <b>2nd generation (cetirizine, fexofenadine, loratadine) &rarr; little sedation.</b>","s":10},{"t":"Named agents","d":"<b>Promethazine</b> = strongest antimuscarinic, motion sickness. Meclizine, hydroxyzine = high antiemetic. <b>Azelastine</b> = nasal H1 blocker; <b>bitter taste, epistaxis</b>.","s":10},{"t":"H1 uses","d":"Allergic rhinitis, urticaria, insect bites, drug reactions; motion sickness and vestibular upset; sleep aids; <b>adjuvant</b> in anaphylaxis.","s":10},{"t":"Nasal steroids","d":"Beclomethasone, budesonide, flunisolide, <b>fluticasone (Flonase, not Flovent)</b>, mometasone, triamcinolone. Allergic/vasomotor rhinitis. <b>Epistaxis, septal perforation</b>, bad taste.","s":10},{"t":"Systemic steroids","d":"Dexamethasone, prednisone/prednisolone. Fluid/sodium retention, <b>potassium loss</b>, hyperglycemia, <b>tendon rupture</b>, cataract/glaucoma, infection. <b>Contraindicated in systemic fungal infection.</b> Dexamethasone + diuretic &rarr; hypokalemia (&rarr; arrhythmia with digoxin); macrolides &darr; its clearance. <b>Do not stop abruptly</b>; avoid live vaccines on prednisone.","s":10},{"t":"Decongestants","d":"All <b>alpha agonists</b>. <b>Oxymetazoline</b> spray: <b>3&ndash;5 days max &rarr; rebound rhinitis (rhinitis medicamentosa)</b>; MAOI (monoamine oxidase inhibitor) interaction. <b>Pseudoephedrine</b> oral: tachycardia, hypertension, headache; <b>&darr; antihypertensive effect</b>; eustachian tube dysfunction. Phenylephrine = pseudoephedrine-free (Sudafed PE).","s":11},{"t":"Spray technique","d":"Head down, <b>aim away from the septum</b>, <b>right hand &rarr; left nostril</b>, don&rsquo;t tilt back, no other sprays; nosebleed &rarr; stop and follow up.","s":11},{"t":"Antitussives","d":"<b>Benzonatate</b>: numbs lung <b>stretch receptors</b>; non-productive cough; <b>swallow whole</b> (chewing numbs mouth); tetracaine allergy. <b>Dextromethorphan</b>: <b>medullary cough center, sigma receptor</b>; <b>serotonin syndrome</b>; no MAOI within 2 weeks.","s":11},{"t":"Mucus","d":"<b>Guaifenesin</b>: expectorant, &darr; viscosity; fluids; expect more drainage. <b>Dornase alfa</b>: cleaves neutrophil DNA in cystic fibrosis sputum. Hypertonic saline. <b>N-acetylcysteine</b>: splits disulfide bonds; <b>rotten-egg smell, bronchospasm</b>; also the acetaminophen antidote.","s":11},{"t":"NOT on it","d":"Diuretics/heart-failure drugs (Lecture 9, Exam 3) &middot; which ACE (angiotensin-converting enzyme) inhibitors are prodrugs &middot; elimination routes &middot; <b>plus counts</b> in the CCB (calcium channel blocker) table &middot; MSA/ISA columns &middot; carteolol, betaxolol, terazosin/doxazosin detail &middot; AT2 (angiotensin II type 2 receptor) &middot; doses.","s":12},{"t":"Suffixes","d":"-pril ACE inhibitor &middot; -sartan ARB (angiotensin receptor blocker) &middot; -dipine DHP (dihydropyridine) CCB &middot; -olol beta blocker (<b>N&ndash;Z non-selective, A&ndash;M beta-1 selective</b>; carvedilol, labetalol exceptions) &middot; -zosin alpha-1 blocker.","s":12},{"t":"★★ HYPERKALEMIA","d":"ACE inhibitors AND ARBs (angiotensin receptor blockers): <b>renal disease, potassium-sparing diuretics, K+ (potassium) supplements, salt substitutes</b>. His strongest cue: &ldquo;very easy test question.&rdquo;","s":12},{"t":"★ ACE inhibitor uses","d":"<b>Preferred in diabetics (kidney protective)</b>; <b>all with LV (left ventricular) dysfunction unless contraindicated</b>; post-MI; diabetic nephropathy. Enalaprilat = intravenous.","s":12},{"t":"★ ACE inhibitor harms","d":"<b>Dry cough</b> (bradykinin, substance P; 1 week&ndash;6 months). <b>Angioedema</b> (bradykinin, first week). First-dose hypotension (sodium-depleted, heart failure, multiple drugs). <b>GFR (glomerular filtration rate) drops dramatically</b> if angiotensin-dependent &rarr; start low, go slow. <b>2nd/3rd trimester contraindicated.</b> NSAIDs &darr; effect.","s":12},{"t":"★ ARB vs ACE inhibitor","d":"ARBs block <b>AT1 (angiotensin II type 1 receptor)</b>; <b>don&rsquo;t touch bradykinin &rarr; NO cough, less angioedema &rarr; the switch</b>. Same hyperkalemia and pregnancy rules. For LV dysfunction when an ACE inhibitor is not tolerated. Add a diuretic for more effect.","s":12},{"t":"★ THE SPLIT","d":"<b>Non-DHP (diltiazem, verapamil) = HEART</b>: slow AV (atrioventricular) conduction, &darr; rate and contractility (verapamil most). <b>DHP (dihydropyridine) (-dipine) = VESSELS</b>: no AV effect. Arteries 3&ndash;10&times; more sensitive; afterload &darr;, preload unchanged.","s":13},{"t":"★ Non-DHP","d":"Angina, hypertension, <b>SVT (supraventricular tachycardia)</b> (atrial fibrillation/flutter, PSVT (paroxysmal supraventricular tachycardia)). <b>1st-degree AV block, bradycardia, worse heart failure</b>, <b>constipation</b>, gingival hyperplasia. Contraindicated: advanced heart block, hypotension (relative: heart failure, liver disease, GERD (gastroesophageal reflux disease)).","s":13},{"t":"★ CYP3A4 (cytochrome P450 3A4) + P-gp (P-glycoprotein)","d":"Non-DHPs <b>inhibit CYP3A4</b> (&uarr; atorvastatin, lovastatin, simvastatin, carbamazepine, propranolol, tacrolimus, cyclosporine) and <b>P-glycoprotein</b> (&uarr; digoxin). DHPs (dihydropyridines) are substrates only.","s":13},{"t":"★ DHP","d":"<b>Rebound (reflex) tachycardia</b>, peripheral edema, gingival hyperplasia. <b>Nimodipine = subarachnoid hemorrhage.</b> Nicardipine = the intravenous one. Contraindicated: <b>severe aortic stenosis</b>; unstable angina/recent MI (myocardial infarction) with immediate release.","s":13},{"t":"Beta blocker + non-DHP","d":"Synergistic &darr; BP (blood pressure), rate, contractility &rarr; <b>lower doses of each</b> (the slide allows it).","s":13},{"t":"Generations","d":"1st non-selective (nadolol, pindolol, <b>propranolol</b>, sotalol, timolol) &middot; 2nd beta-1 selective (acebutolol, atenolol, bisoprolol, <b>esmolol IV (intravenous)</b>, metoprolol) &middot; 3rd vasodilating: <b>★ carvedilol, labetalol = alpha-1 block too</b>.","s":14},{"t":"★ Hypertension","d":"<b>Not first line.</b> Work best in young (tachycardia, high renin); fatigue, less exercise tolerance. First after MI (myocardial infarction).","s":14},{"t":"★ Heart failure trio","d":"<b>Carvedilol, metoprolol succinate, bisoprolol</b> &mdash; start very low, increase slowly (worsen at first).","s":14},{"t":"Other uses","d":"Glaucoma (timolol), migraine prophylaxis (propranolol, timolol), hyperthyroidism (&darr; T4&rarr;T3), angina, acute MI (avoid ISA (intrinsic sympathomimetic activity)), SVT (supraventricular tachycardia), panic, essential tremor.","s":14},{"t":"★ Harms","d":"Bronchospasm (<b>less with beta-1 selective</b>; contraindicated in COPD (chronic obstructive pulmonary disease) with bronchospasm) &middot; bradycardia, heart block &middot; <b>masked, prolonged hypoglycemia</b> &middot; cold extremities, claudication &middot; <b>sudden withdrawal &rarr; angina, MI, high BP (blood pressure): taper</b> &middot; <b>propranolol (lipid soluble) &rarr; depression, nightmares</b> &middot; &uarr; triglycerides.","s":14},{"t":"Alpha-1 blockers","d":"Prazosin: <b>orthostatic hypotension</b>, mild reflex tachycardia, sodium retention, impotence; lipids improve; NSAIDs blunt, beta blockers worsen postural drop. Terazosin/doxazosin: once daily, BPH (benign prostatic hyperplasia) too. <b>Tamsulosin = alpha-1A &rarr; BPH, little vascular effect.</b>","s":15},{"t":"Central alpha-2 agonists","d":"&darr; sympathetic outflow (brainstem). Sedation, dry mouth, <b>narrow therapeutic range</b>, <b>★ abrupt-withdrawal hypertension</b>; lipid-neutral. <b>Clonidine</b>: sodium retention (+ diuretic), &uarr; glucose, blunts opiate withdrawal. <b>Guanfacine</b>: most alpha-2 selective, less sedation. (Slide 75&rsquo;s &ldquo;blocker&rdquo; is a slip &mdash; AGONIST.)","s":15},{"t":"★ Hydralazine","d":"<b>N-acetylated &rarr; fast/slow acetylators</b>; <b>lupus syndrome</b> (high dose, long term, women, slow acetylators, Caucasians); contraindicated in CAD (coronary artery disease), elderly, ischemia; <b>stools may turn black</b>.","s":15},{"t":"Minoxidil / nitroprusside","d":"Minoxidil: <b>K+ (potassium) channel opener</b>; severe reflexes, ischemia, arrhythmia, <b>hypertrichosis</b>; triple therapy for refractory HTN (hypertension). Nitroprusside IV (intravenous) for <b>hypertensive crisis</b>; veins + arterioles; <b>cyanide &rarr; sodium thiosulfate</b>; thiocyanate with long infusion/renal failure.","s":15},{"t":"★ Algorithm","d":"&gt;20/10 above goal &rarr; <b>ACE (angiotensin-converting enzyme) inhibitor (OR ARB (angiotensin receptor blocker)) + DHP (dihydropyridine)</b>. Albuminuria (ACR (urine albumin-to-creatinine ratio) &ge;300) &rarr; <b>ACE inhibitor or ARB</b>. Otherwise one of them &rarr; combine &rarr; <b>+ thiazide-like diuretic</b>. Reassess at <b>~4 weeks</b>. Failure: <b>nonadherence</b>, white coat, bad measurement.","s":15},{"t":"NOT on it","d":"Picking an intensity for a scenario &middot; calculating 10-year risk &middot; statin PK (pharmacokinetics) table except the CYP row &middot; IDL (intermediate-density lipoprotein) &middot; ezetimibe + cyclosporine &middot; doses.","s":16},{"t":"Memory aid (not fact)","d":"Liver = depot; LDL (low-density lipoprotein) = delivery truck (ApoB-100 (apolipoprotein B-100) badge); <b>LDL receptor = receiving gate</b>; HDL (high-density lipoprotein) = <b>garbage truck</b>; VLDL (very-low-density lipoprotein) = fuel tanker; PCSK9 (proprotein convertase subtilisin/kexin type 9) = demolition crew; bile = sewer.","s":16},{"t":"The drugs in the story","d":"<b>Statins</b> cut the depot&rsquo;s own output + add gates &middot; <b>ezetimibe</b> narrows the port&rsquo;s import gate &middot; <b>resins</b> block the sewer&rsquo;s recycling (more gates, but more tankers &rarr; TG (triglycerides) &uarr;) &middot; <b>fibrates</b> fewer tankers, more garbage trucks &middot; <b>niacin</b> cuts the fuel line from fat stores &middot; <b>PCSK9 inhibitors</b> stop the demolition crew.","s":16},{"t":"★ Key point","d":"Statins, ezetimibe, resins, PCSK9 inhibitors all end in <b>more hepatic LDL receptors</b>.","s":16},{"t":"★ Mechanism","d":"HMG-CoA (3-hydroxy-3-methylglutaryl coenzyme A) reductase &darr; &rarr; less liver cholesterol &rarr; <b>&uarr; LDL (low-density lipoprotein) receptors</b> &rarr; &darr; LDL. Pleiotropic: plaque stabilization, endothelium, antithrombotic.","s":17},{"t":"★ First line","d":"<b>Most efficacious, best tolerated</b>; first line whenever LDL lowering is indicated. &ldquo;10 times out of 10.&rdquo;","s":17},{"t":"★ CYP3A4 (cytochrome P450 3A4)","d":"<b>Atorvastatin, lovastatin, simvastatin</b>; rosuvastatin minimal CYP; pravastatin non-CYP. Interactions: <b>verapamil, amiodarone, niacin, fibrates, GRAPEFRUIT JUICE</b>.","s":17},{"t":"★ Harms","d":"Liver enzymes &uarr; 0.5&ndash;2.5%, <b>serious liver problems exceedingly rare</b> &rarr; reduce/hold. <b>Myalgia &rarr; myopathy &rarr; rare rhabdomyolysis</b>; <b>combine with fibrates cautiously</b>; muscle toxicity &rarr; STOP.","s":17},{"t":"★ Contraindications","d":"<b>Hepatic disease, pregnancy.</b> Relative: cyclosporine, <b>gemfibrozil</b>, niacin, erythromycin.","s":17},{"t":"★ AHA/ACC (American Heart Association and American College of Cardiology)","d":"Moderate/high intensity for the 4 groups; <b>no LDL target</b>; recheck lipids for <b>adherence</b>. Groups: <b>clinical ASCVD (atherosclerotic cardiovascular disease) &middot; LDL &gt;190 &middot; diabetes 40&ndash;75 with LDL 70&ndash;189 &middot; 10-year risk &gt;7.5% with LDL 70&ndash;189</b>.","s":17},{"t":"★ Intensity","d":"High &ge;50% LDL fall = <b>atorvastatin, rosuvastatin only</b>; moderate 30&ndash;49%; low &lt;30%. Not tolerated &rarr; maximum tolerated dose. Recheck LDL at 6 weeks (expect 30&ndash;50%).","s":17},{"t":"Ezetimibe","d":"&darr; intestinal cholesterol absorption &rarr; &uarr; LDL (low-density lipoprotein) receptors; add-on to a statin; enterohepatic (glucuronide); transaminases &uarr; with statin; <b>antacids and resins &darr; levels</b>; fibrates &rarr; gallstones.","s":18},{"t":"★ Resins","d":"Cholestyramine, colestipol, colesevelam. Bind bile acids &rarr; &uarr; LDL receptors. <b>Not absorbed &rarr; children, adolescents, PREGNANCY</b>; poorly tolerated; constipation; <b>ADEK (vitamins A, D, E and K) + folate malabsorption</b>; <b>&uarr; VLDL (very-low-density lipoprotein) &rarr; TG (triglycerides) &uarr;</b>.","s":18},{"t":"★ Resin contraindication","d":"<b>Absolute: TG &gt;400, familial dysbetalipoproteinemia. Relative: TG &gt;200.</b> TG 600 &rarr; the resin is the wrong answer.","s":18},{"t":"★ Resin administration","d":"Mix powder in water/pulpy juice; <b>within 1 h of a meal</b>; other drugs (<b>digoxin, warfarin, thyroxine, beta blockers, thiazides</b>) <b>1 h before or 4 h after</b>.","s":18},{"t":"★ Fibrates","d":"<b>PPAR-alpha (peroxisome proliferator-activated receptor alpha)</b> &rarr; &darr; VLDL/TG, &uarr; ApoA-1/HDL. <b>TG &gt;1000 or low HDL (high-density lipoprotein).</b> Gallstones, myopathy. Contraindicated: pregnancy, severe hepatic/renal disease, gallbladder disease. <b>&uarr; warfarin effect.</b>","s":18},{"t":"★ Niacin","d":"&darr; FFA (free fatty acids) from fat &rarr; &darr; VLDL, LDL; <b>biggest HDL rise</b>. <b>Flushing = prostaglandins &rarr; aspirin first.</b> &uarr; LFTs (liver function tests), glucose, uric acid. <b>Absolute: chronic liver disease</b>; relative: peptic ulcer, gout, hyperuricemia, diabetes. Alcohol interacts. Niacinamide is NOT an antilipemic.","s":18},{"t":"PCSK9 (proprotein convertase subtilisin/kexin type 9) inhibitors","d":"Alirocumab, evolocumab: <b>monoclonal antibodies, injectable only</b>, expensive; keep LDL receptors active; <b>hypersensitivity</b> is the most serious reaction.","s":18},{"t":"★ Which lipid","d":"LDL &rarr; statins. <b>TG &darr; + HDL &uarr; &rarr; niacin, fibrates.</b> <b>Resins are the only class bad for TG.</b>","s":18}],"map":{"pharmacology-i-exam-2-allergy-inflammation-quiz-version-2":[-1,22,31,28,-1,-1,-1,25,-1,-1,25,24,-1,-1,-1,-1,-1],"pharmacology-i-exam-2-allergy-inflammation-quiz":[23,-1,31,46,-1,26,27,30,31,32,-1,24,46,-1,-1,-1,25],"pharmacology-i-exam-2-anti-infectives-quiz-version-2":[11,-1,-1,9,18,16,-1,6,20,11,12,13,44,-1,-1,-1,13,-1,-1,7,-1],"pharmacology-i-exam-2-anti-infectives-quiz":[20,16,10,6,17,19,10,12,11,10,8,21,-1,-1,-1,-1,18,9,20,-1],"pharmacology-i-exam-2-ent-analgesics-quiz-version-2":[57,56,53,57,56,55,53,-1,57,56,57,58,56,58,-1,-1,-1],"pharmacology-i-exam-2-ent-analgesics-quiz":[-1,-1,58,57,55,54,55,57,57,57,55,56,55,58,56,53,-1],"pharmacology-i-exam-2-ent-anti-infectives-quiz-version-2":[48,51,48,-1,-1,-1,50,50,-1,51,51,49,48,50,51,-1,48,48,50],"pharmacology-i-exam-2-ent-anti-infectives-quiz":[-1,-1,48,48,51,-1,-1,-1,48,48,49,47,-1,51,50,48,14,48,-1],"pharmacology-i-exam-2-ent-antihistamines-steroids-quiz-version-2":[-1,-1,-1,63,66,64,-1,61,64,66,-1,-1,63,2,-1,-1,64,63,-1],"pharmacology-i-exam-2-ent-antihistamines-steroids-quiz":[-1,64,-1,-1,-1,14,63,-1,-1,-1,-1,66,59,-1,7,14,14,-1],"pharmacology-i-exam-2-ent-decongestants-cough-quiz-version-2":[-1,-1,-1,-1,-1,68,-1,94,-1,-1,-1,67,-1,-1,-1,67,-1,-1],"pharmacology-i-exam-2-ent-decongestants-cough-quiz":[-1,-1,-1,-1,-1,68,-1,67,-1,-1,65,-1,-1,-1,-1,68,67,68],"pharmacology-i-exam-2-glaucoma-diagnostics-quiz-version-2":[41,40,37,43,38,-1,41,42,39,-1,37,34,38,-1,42,-1,41],"pharmacology-i-exam-2-glaucoma-diagnostics-quiz":[36,42,-1,-1,37,36,33,36,-1,23,35,37,39,4,34,95],"pharmacology-i-exam-2-htn-alpha-central-vasodilators-quiz-version-2":[86,87,-1,86,88,88,85,85,85,-1,86,-1,88,88,-1,87],"pharmacology-i-exam-2-htn-alpha-central-vasodilators-quiz":[88,-1,-1,-1,85,87,85,86,88,-1,87,85,-1,86,85,88,94],"pharmacology-i-exam-2-htn-beta-blockers-quiz-version-2":[-1,14,-1,95,81,-1,-1,80,36,79,-1,2,-1,83],"pharmacology-i-exam-2-htn-beta-blockers-quiz":[-1,-1,36,-1,80,-1,14,82,81,-1,70,84,-1,82],"pharmacology-i-exam-2-htn-calcium-channel-blockers-quiz-version-2":[-1,77,-1,-1,78,-1,-1,76,-1,-1,14,76,79,-1,-1,98],"pharmacology-i-exam-2-htn-calcium-channel-blockers-quiz":[-1,-1,-1,-1,78,77,-1,77,78,-1,76,77,-1,-1,98,-1],"pharmacology-i-exam-2-htn-raas-inhibitors-quiz-version-2":[71,-1,89,74,-1,69,89,73,89,73,72,69,73,73,74,-1,74,73],"pharmacology-i-exam-2-htn-raas-inhibitors-quiz":[72,-1,-1,72,-1,-1,71,-1,-1,73,-1,71,73,-1,-1,-1,89,-1],"pharmacology-i-exam-2-lipid-fibrates-niacin-quiz-version-2":[106,98,105,101,106,-1,-1,-1,108,108,105,106,108,106],"pharmacology-i-exam-2-lipid-fibrates-niacin-quiz":[98,14,108,-1,-1,-1,108,108,106,106,108,105,108,105],"pharmacology-i-exam-2-lipid-resins-ezetimibe-pcsk9-quiz-version-2":[101,102,-1,104,104,-1,102,101,102,94,103,101,101,107],"pharmacology-i-exam-2-lipid-resins-ezetimibe-pcsk9-quiz":[-1,107,101,102,-1,101,103,101,101,102,107,-1,102,101,-1],"pharmacology-i-exam-2-lipid-statins-quiz-version-2":[100,101,98,95,98,-1,96,94,97,98,100,94,-1,99,94],"pharmacology-i-exam-2-lipid-statins-quiz":[91,94,-1,101,99,97,96,14,-1,98,96,94,96,101,100,100],"pharmacology-i-exam-2-pharm-e2-drill-allergy-inflammation":[22,7,-1,23,-1,24,24,25,25,7,-1,28,28,-1,30,30,29,-1,32,32,31,26],"pharmacology-i-exam-2-pharm-e2-drill-anti-infectives":[-1,-1,-1,-1,-1,12,-1,-1,18,-1,-1,-1,-1,14,-1,20,20,18,18,19,17,-1,-1,9,9,7],"pharmacology-i-exam-2-pharm-e2-drill-antihypertensives":[73,74,72,-1,71,-1,78,-1,77,77,78,-1,84,82,-1,82,-1,83,80,85,91,86,86,-1,87,87,88,88,87],"pharmacology-i-exam-2-pharm-e2-drill-glaucoma-diagnostics":[35,35,35,36,36,36,36,37,37,38,38,-1,39,-1,-1,-1,21,41,41,42,42,43,34,34,37],"pharmacology-i-exam-2-pharm-e2-drill-lipids":[96,96,101,-1,100,100,101,101,105,-1,98,102,102,102,104,106,106,106,106,105,107,107,101,95],"pharmacology-i-exam-2-pharm-e2-master-drill":[-1,22,35,73,96,-1,7,35,74,96,-1,-1,35,72,101,-1,23,36,-1,-1,-1,-1,36,71,100,12,24,36,-1,100,-1,24,36,78,101,-1,25,37,-1,101,18,25,37,77,105,-1,7,38,77,-1,-1,-1,38,78,98,-1,28,-1,-1,102,-1,28,39,84,102,14,-1,-1,82,102,-1,30,-1,-1,104,20,30,-1,82,106,20,29,21,-1,106,18,-1,41,83,106,18,32,41,80,106,19,32,42,85,105,17,31,42,91,107,-1,26,43,86,107,-1,34,86,101,9,34,-1,95,9,37,87,7,87,88,88,87],"pharmacology-i-exam-2-pharm-e2-vignettes-version-2":[-1,-1,42,14,41,-1,-1,29,-1,-1,-1,-1,23,-1,-1,36,36,-1,21,-1,-1],"pharmacology-i-exam-2-pharm-e2-vignettes":[34,-1,-1,-1,-1,32,14,-1,-1,30,17,43,46,-1,20,44,24,-1,-1,-1,44]}};
